def is_safe_path(path, base):
    """
    Check if the resolved path stays inside the directory base.
    Return True if the path does, and False otherwise.
    """
    base_path = base.split('/')
    path = path.split('/')
    if path[0] != base_path[0]:
        return False
    if len(path) == len(base_path):
        return True
    if path[1] != base_path[1]:
        return False
    return is_safe_path(path[2:], base_path[2:])

